using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;
namespace ParkingLotEnvironment.CloudPilot {public static class RoofRepair {
 public static int Apply(GameObject root){const string w="Assets/ParkingLotEnvironment/CloudPilot/WholeMapFinish20261105";var roof=AssetDatabase.LoadAssetAtPath<Material>(w+"/ConcreteRoofFinish.mat");if(!roof){roof=new Material(Shader.Find("ParkingLot/WholeMap/Concrete")){name="ConcreteRoofFinish",color=new Color(.38f,.4f,.37f)};AssetDatabase.CreateAsset(roof,w+"/ConcreteRoofFinish.mat");}int count=0;
 var buildings=new List<Transform>();var source=root.transform.Find("AG_Photorealistic3D_Assets");if(source)foreach(Transform t in source)if(t.name.Contains("ContextBuilding"))buildings.Add(t);var context=root.transform.Find("ParkingContext_ApprovedKitExtension");if(context)foreach(Transform t in context)if(!t.name.Contains("Roof")&&!t.name.Contains("Parapet"))buildings.Add(t);
 foreach(var building in buildings){if(building.Find("ConcreteRoofSurface"))continue;var rr=building.GetComponentsInChildren<Renderer>().Where(r=>r.enabled&&r.gameObject.activeInHierarchy).ToArray();if(rr.Length==0)continue;var b=rr[0].bounds;foreach(var r in rr.Skip(1))b.Encapsulate(r.bounds);if(b.size.y<3)continue;float y=b.max.y+.015f;var pts=new[]{new Vector3(b.min.x,y,b.min.z),new Vector3(b.min.x,y,b.max.z),new Vector3(b.max.x,y,b.max.z),new Vector3(b.max.x,y,b.min.z)};var mesh=new Mesh{name="RoofSurface_"+count};mesh.vertices=pts.Select(p=>building.InverseTransformPoint(p)).ToArray();mesh.uv=new[]{Vector2.zero,Vector2.up,Vector2.one,Vector2.right};mesh.triangles=new[]{0,1,2,0,2,3};mesh.RecalculateNormals();mesh.RecalculateTangents();Unwrapping.GenerateSecondaryUVSet(mesh);AssetDatabase.CreateAsset(mesh,w+"/RoofSurface_"+count+".asset");var g=new GameObject("ConcreteRoofSurface");g.transform.SetParent(building,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;var renderer=g.AddComponent<MeshRenderer>();renderer.sharedMaterial=roof;renderer.receiveGI=ReceiveGI.Lightmaps;renderer.scaleInLightmap=.15f;GameObjectUtility.SetStaticEditorFlags(g,StaticEditorFlags.ContributeGI|StaticEditorFlags.ReflectionProbeStatic);count++;}
 AssetDatabase.SaveAssets();if(count==0)throw new Exception("No roof surfaces repaired");return count;}
}}
